.form-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.25rem 2.5rem;
}

.form-card__header {
  margin-bottom: 1.5rem;
}

.form-card__header h1 {
  font-size: 1.625rem;
  font-weight: 700;
