(function () {
  "use strict";

  /* ── Helpers ──────────────────────────────────────────────────────── */

  /** Return trimmed value of an input element. */
  function val(input) {
    return input.value.trim();
  }

  /** Mark a field as invalid: show error, set aria attributes. */
  function setInvalid(input, errorEl, message) {
    input.setAttribute("aria-invalid", "true");
    errorEl.textContent = message;
    errorEl.removeAttribute("hidden");
  }

  /** Mark a field as valid: hide error, remove aria-invalid. */
  function setValid(input, errorEl) {
    input.removeAttribute("aria-invalid");
    errorEl.textContent = "";
    errorEl.setAttribute("hidden", "");
  }

  /* ── Field validators ─────────────────────────────────────────────── */

  function validateFullName(input, errorEl) {
    const v = val(input);
    if (!v) {
      setInvalid(input, errorEl, "Error: Full name is required.");
      return false;
    }
    setValid(input, errorEl);
    return true;
  }

  function validateEmail(input, errorEl) {
    const v = val(input);
    if (!v) {
      setInvalid(input, errorEl, "Error: Email address is required.");
      return false;
    }
    // Basic structural check; browser type="email" handles the rest.
    if (!v.includes("@") || !v.includes(".")) {
      setInvalid(
        input,
        errorEl,
        "Error: Enter a valid email address, e.g. name@example.com."
      );
      return false;
    }
    setValid(input, errorEl);
    return true;
  }

  /* ── Init ─────────────────────────────────────────────────────────── */

  document.addEventListener("DOMContentLoaded", function () {
    const form       = document.getElementById("contact-form");
    const nameInput  = document.getElementById("full-name");
    const nameError  = document.getElementById("full-name-error");
    const emailInput = document.getElementById("email");
    const emailError = document.getElementById("email-error");
    const statusEl   = document.getElementById("form-status");

    if (!form) return;

    /** Flag flips true after the first submit attempt. */
    let submitted = false;

    /* Live validation fires only after the first submit attempt so that
       fields don't show errors before the user has had a chance to fill
       them in. */
    nameInput.addEventListener("input", function () {
      if (submitted) validateFullName(nameInput, nameError);
    });

    emailInput.addEventListener("input", function () {
      if (submitted) validateEmail(emailInput, emailError);
    });

    /* Also validate on blur after first submit to catch tab-away. */
    nameInput.addEventListener("blur", function () {
      if (submitted) validateFullName(nameInput, nameError);
    });

    emailInput.addEventListener("blur", function () {
      if (submitted) validateEmail(emailInput, emailError);
    });

    /* ── Submit handler ─────────────────────────────────────────────── */
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      submitted = true;

      // Hide any previous status message.
      statusEl.setAttribute("hidden", "");
      statusEl.className = "form-status";
      statusEl.textContent = "";

      const nameOk  = validateFullName(nameInput, nameError);
      const emailOk = validateEmail(emailInput, emailError);

      if (!nameOk || !emailOk) {
        // Move focus to the first invalid field.
        if (!nameOk) {
          nameInput.focus();
        } else {
          emailInput.focus();
        }
        return;
