        "✓ Message sent! We'll be in touch within one business day.";

      form.reset();
      // Clear any lingering aria-invalid states after reset.
      [nameInput, emailInput].forEach(function (el) {
        el.removeAttribute("aria-invalid");
      });
      submitted = false;
    });
  });
})();
