  background-color: var(--color-bg);
  color: var(--color-text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  line-height: 1.6;
}

/* ── Skip link ─────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 100;
}

.skip-link:focus {
  top: 1rem;
}

/* ── Screen-reader only ────────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ────────────────────────────────────────────────────────── */
.site-header {
  background-color: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 0 1.5rem;
}

.site-header__inner {
  max-width: 640px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.site-header__logo {
  font-size: 1.25rem;
  color: var(--color-accent);
}

.site-header__brand {
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--color-text-primary);
}

/* ── Main content area ─────────────────────────────────────────────── */
main {
  flex: 1;
  padding: 3rem 1rem 4rem;
}

.form-section {
  max-width: 520px;
  margin: 0 auto;
}

/* ── Card ──────────────────────────────────────────────────────────── */
.form-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.25rem 2.5rem;
}

.form-card__header {
  margin-bottom: 1.5rem;
}

.form-card__header h1 {
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1.25;
}

.form-card__subtitle {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-muted);
}

/* ── Required legend ───────────────────────────────────────────────── */
.required-legend {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}

.required-legend .required-marker {
  color: var(--color-required);
  font-weight: 700;
}

/* ── Form fields ───────────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.form-field label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text-primary);
}

.required-marker {
  color: var(--color-required);
  margin-left: 0.1875rem;
  font-weight: 700;
}

