  border-color: var(--color-border-error);
}

.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.3);
}

/* ── Help & error text ─────────────────────────────────────────────── */
.field-help {
